def xor_distance(a: bytes, b: bytes) -> int:
    # WHY XOR: symmetric, unidirectional, maps to prefix tree.
    # Closeness here means shared prefix, not geography.
    return int.from_bytes(a, 'big') ^ int.from_bytes(b, 'big')

def select_closest(target: bytes, candidates: list, alpha: int = 3):
    # Trade-off: larger alpha = faster + more robust, but more chatter.
    # Production Kademlia uses alpha=3, k=20 for this reason.
    ranked = sorted(candidates, key=lambda p: xor_distance(target, p.node_id))
    return ranked[:alpha]
